package com.suresh.lifeos;
import java.nio.charset.StandardCharsets;import java.security.SecureRandom;import java.util.Base64;import javax.crypto.*;import javax.crypto.spec.*;
public final class Crypto { private Crypto(){} public static String enc(String s,String p)throws Exception{SecureRandom r=new SecureRandom();byte[] salt=new byte[16],iv=new byte[12];r.nextBytes(salt);r.nextBytes(iv);SecretKeyFactory f=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");SecretKeySpec k=new SecretKeySpec(f.generateSecret(new PBEKeySpec(p.toCharArray(),salt,120000,256)).getEncoded(),"AES");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,k,new GCMParameterSpec(128,iv));return "LIFEOS1\n"+Base64.getEncoder().encodeToString(salt)+"\n"+Base64.getEncoder().encodeToString(iv)+"\n"+Base64.getEncoder().encodeToString(c.doFinal(s.getBytes(StandardCharsets.UTF_8)));} public static String dec(String s,String p)throws Exception{String[] a=s.split("\\n");if(a.length<4||!"LIFEOS1".equals(a[0]))throw new IllegalArgumentException("Not a Life OS backup");byte[] salt=Base64.getDecoder().decode(a[1]),iv=Base64.getDecoder().decode(a[2]),ct=Base64.getDecoder().decode(a[3]);SecretKeyFactory f=SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");SecretKeySpec k=new SecretKeySpec(f.generateSecret(new PBEKeySpec(p.toCharArray(),salt,120000,256)).getEncoded(),"AES");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,k,new GCMParameterSpec(128,iv));return new String(c.doFinal(ct),StandardCharsets.UTF_8);}}
